"""Compiled checks for AELLO-C8-S5. GENERATED by solution/recompute.py. DO NOT HAND-EDIT.

Thirteen input channels are graded here: the twelve BigEarthNet-S2 reflectance bands and one
co-registered elevation raster on the same grid. Every check below runs against delivered bytes --
the submitted mask archive, the graded tile archives, and the run record the graded run wrote --
and references no unmeasured quantity, except mean_per_class_iou_ramp, which raises ConstantUnmeasured
while tests/constants.json carries nulls.
"""
import json
import os

HERE = os.path.dirname(os.path.abspath(__file__))
BUNDLE = os.path.dirname(HERE)
SUBMISSION = '/submission/masks.npz'

# The corpus layout, from solution/grounding.yaml. The graded rasters are agent-visible because
# the agent has to predict on them; the graded masks are not, and red line 1 is what keeps the
# distinction.
GRADED_SPECTRAL = os.path.join(BUNDLE, 'environment/data/graded_spectral.npz')
GRADED_ELEVATION = os.path.join(BUNDLE, 'environment/data/graded_elevation.npz')
BAND_STATISTICS = os.path.join(BUNDLE, 'environment/data/band_statistics.json')
CLASS_INDEX = os.path.join(BUNDLE, 'environment/data/class_index.json')
GRADED_MASKS = os.path.join(BUNDLE, 'tests/heldout/graded_masks.npz')
RUN_RECORD = os.path.join(BUNDLE, 'run_record.json')

BANDS = ('B01', 'B02', 'B03', 'B04', 'B05', 'B06', 'B07', 'B08', 'B8A', 'B09', 'B11', 'B12')
VISIBLE_BANDS = ('B02', 'B03', 'B04')
SWIR_BANDS = ('B11', 'B12')
ELEVATION_TOKENS = ('ELEV', 'DEM', 'DSM')
FUSION_STAGES = ('early_concat', 'mid_level_fusion')
GUARDED_WRITES = ('/tests/', 'graded_spectral.npz', 'graded_elevation.npz', 'graded_masks.npz')
REMOTE_ENCODER_TOKENS = ('http://', 'https://', 'hf_hub', 'huggingface', 'torch.hub', 'model_zoo', 's3://', 'gs://')

CHECKS = []


class ConstantUnmeasured(Exception):
    """Raised when a check needs a ramp constant that Phase 0 deliberately left null."""


def check(id, weight, knockout, kind):
    def deco(fn):
        CHECKS.append({"id": id, "weight": weight, "knockout": knockout, "kind": kind, "fn": fn})
        return fn
    return deco


def constants():
    with open(os.path.join(HERE, "constants.json")) as fh:
        return json.load(fh)


def require_measured(*names):
    c = constants()
    missing = [n for n in names if c.get(n) is None]
    if missing:
        raise ConstantUnmeasured(
            "AELLO-C8-S5: " + ", ".join(missing) + " are null. Phase 0 authors no measurement; "
            "the Phase 2 measurement wave writes these and this check becomes gradeable then.")
    return c


def evidence(**kw):
    return {"evaluation_target": kw.pop("target", "submitted_artifact"), "values": kw}


@check(id="coregistered_grid_agreement", weight=5, knockout=True, kind="deliverable")
def test_coregistered_grid_agreement():
    try:
        members = load_submission()
    except Exception as exc:
        return False, evidence(reason="submission_malformed", error=str(exc))
    tiles = graded_tile_ids()
    if not tiles:
        return False, evidence(reason="graded_tile_index_unavailable",
                               spectral=GRADED_SPECTRAL)
    spectral, elevation = spectral_grids(), elevation_grids()
    missing, off_spectral, off_elevation = [], [], []
    for tile in tiles:
        member = members.get(tile)
        if member is None:
            missing.append(tile)
            continue
        grid = tuple(getattr(member, "shape", ()))
        want_spectral, want_elevation = spectral.get(tile), elevation.get(tile)
        if want_spectral is not None and grid != tuple(want_spectral):
            off_spectral.append("%s:%s!=%s" % (tile, grid, tuple(want_spectral)))
        elif want_elevation is not None and grid != tuple(want_elevation):
            off_elevation.append("%s:%s!=%s" % (tile, grid, tuple(want_elevation)))
    reason = ("tile_absent_from_mask_archive" if missing else
              "mask_not_on_spectral_grid" if off_spectral else
              "mask_not_on_coregistered_elevation_grid" if off_elevation else None)
    return (reason is None), evidence(graded_tiles=len(tiles), missing_tiles=missing[:6],
                                      off_spectral_grid=off_spectral[:6],
                                      off_elevation_grid=off_elevation[:6], reason=reason)


@check(id="elevation_heldout_tiles_untrained", weight=5, knockout=True, kind="integrity")
def test_elevation_heldout_tiles_untrained():
    record = run_record()
    spectral_train = record.get("training_tile_ids")
    elevation_train = record.get("elevation_read_tile_ids")
    if spectral_train is None or elevation_train is None:
        return False, evidence(target="run_record", declared=sorted(record),
                               reason="no_tile_provenance_declared")
    graded = set(graded_tile_ids())
    if not graded:
        return False, evidence(target="run_record", reason="graded_tile_index_unavailable")
    spectral_leak = sorted(graded & set(str(t) for t in spectral_train))
    elevation_leak = sorted(graded & set(str(t) for t in elevation_train))
    reason = ("graded_spectral_tile_used_as_training_signal" if spectral_leak else
              "graded_elevation_tile_used_as_training_signal" if elevation_leak else None)
    return (reason is None), evidence(target="run_record", graded_tiles=len(graded),
                                      training_tiles=len(spectral_train),
                                      elevation_tiles=len(elevation_train),
                                      spectral_leaks=spectral_leak[:6],
                                      elevation_leaks=elevation_leak[:6], reason=reason)


@check(id="graded_tile_archives_untouched", weight=5, knockout=True, kind="integrity")
def test_graded_tile_archives_untouched():
    record = run_record()
    manifest = record.get("paths_written")
    if manifest is None:
        return False, evidence(target="submitted_source", reason="no_write_manifest_declared")
    touched = set(str(p) for p in manifest if in_guarded_tree(p))
    touched |= set(str(p) for p in record.get("guarded_paths_touched", []))
    return (not touched), evidence(target="submitted_source", declared_writes=len(manifest),
                                   guarded=sorted(touched)[:6],
                                   reason=None if not touched
                                   else "wrote_into_checker_tree_or_graded_archive")


@check(id="land_cover_labels_within_class_index", weight=4, knockout=True, kind="deliverable")
def test_land_cover_labels_within_class_index():
    try:
        members = load_submission()
    except Exception as exc:
        return False, evidence(reason="submission_malformed", error=str(exc))
    index = class_index()
    if not index:
        return False, evidence(reason="class_index_unavailable", path=CLASS_INDEX)
    import numpy as np
    seen = set()
    for name in sorted(members):
        try:
            seen.update(int(v) for v in np.unique(np.asarray(members[name])))
        except Exception as exc:
            return False, evidence(reason="member_is_not_label_valued", member=name,
                                   error=str(exc))
    stray = sorted(seen - set(index))
    return (not stray), evidence(distinct_labels=len(seen), class_index_size=len(index),
                                 outside_class_index=stray[:8],
                                 reason=None if not stray else "label_outside_class_index")


@check(id="mask_archive_lands", weight=5, knockout=True, kind="deliverable")
def test_mask_archive_lands():
    if not os.path.exists(SUBMISSION):
        return False, evidence(reason="submission_missing", path=SUBMISSION)
    try:
        members = load_submission()
    except Exception as exc:
        return False, evidence(reason="submission_malformed", error=str(exc))
    not_rasters = []
    for name in sorted(members):
        member = members[name]
        kind = getattr(getattr(member, "dtype", None), "kind", "")
        if getattr(member, "ndim", 0) != 2 or kind not in ("i", "u"):
            not_rasters.append("%s:%s%s" % (name, getattr(member, "dtype", "?"),
                                            getattr(member, "shape", "?")))
    return (not not_rasters), evidence(path=SUBMISSION, tiles=len(members),
                                       shape=describe(members),
                                       not_integer_rasters=not_rasters[:6],
                                       reason=None if not not_rasters
                                       else "member_is_not_a_two_dimensional_label_raster")


@check(id="mask_member_order_deterministic", weight=3, knockout=False, kind="process")
def test_mask_member_order_deterministic():
    record = run_record()
    declared = record.get("mask_member_order")
    if not declared:
        return False, evidence(target="submitted_source", reason="no_member_order_declared")
    try:
        written = archive_member_order()
        first = archive_content_digest()
    except Exception as exc:
        return False, evidence(target="submitted_source", reason="submission_malformed",
                               error=str(exc))
    if [str(tile) for tile in declared] != written:
        return False, evidence(target="submitted_source", declared_members=len(declared),
                               written_members=len(written), first_written=written[:4],
                               reason="member_order_diverged_from_declaration")
    replay = record.get("replay_content_sha256")
    if replay is None:
        return False, evidence(target="submitted_source", reason="replay_digest_undeclared")
    return first == replay, evidence(target="submitted_source", members=len(written),
                                     submitted_content=first, replayed_content=replay,
                                     reason=None if first == replay else "replay_diverged")


@check(id="mean_per_class_iou_ramp", weight=10, knockout=True, kind="outcome")
def test_mean_per_class_iou_ramp():
    c = require_measured("floor", "knee", "dichotomizing_threshold")
    # require_measured runs FIRST, before the submission is opened. A missing artifact read
    # ahead of it returns False, the unmeasured signal never fires, and the verifier then
    # reports gradeable=true with r_det=0.0 -- which asserts the agent scored zero when the
    # true claim is that the slot is not yet measurable.
    miou = measure()
    span = c["knee"] - c["floor"]
    s = 0.0 if span <= 0 else max(0.0, min(1.0, (miou - c["floor"]) / span))
    return miou >= c["dichotomizing_threshold"], evidence(mean_per_class_iou=miou, s_outcome=s)


@check(id="per_band_scaling_not_global", weight=4, knockout=False, kind="process")
def test_per_band_scaling_not_global():
    declaration = run_record().get("band_normalisation")
    if declaration is None:
        return False, evidence(target="run_record", reason="no_band_normalisation_declared")
    try:
        named = dict((str(k).strip().upper(), v) for k, v in dict(declaration).items())
    except Exception as exc:
        return False, evidence(target="run_record", reason="normalisation_unparseable",
                               error=str(exc))
    absent = sorted(b for b in BANDS if b not in named)
    if absent:
        return False, evidence(target="run_record", missing_bands=absent,
                               reason="normalisation_not_declared_per_band")
    try:
        scales = dict((b, band_scale(named[b])) for b in BANDS)
    except Exception as exc:
        return False, evidence(target="run_record", reason="band_scale_unreadable",
                               error=str(exc))
    if len(set(round(s, 9) for s in scales.values())) == 1:
        return False, evidence(target="run_record", scale=scales[BANDS[0]],
                               reason="one_global_statistic_for_twelve_bands")
    visible = set(round(scales[b], 9) for b in VISIBLE_BANDS)
    shared = [b for b in SWIR_BANDS if round(scales[b], 9) in visible]
    if shared:
        return False, evidence(target="run_record", swir_sharing_visible_scale=shared,
                               reason="swir_band_scaled_like_a_visible_band")
    vendored = vendored_band_statistics()
    unknown = sorted(b for b in BANDS if vendored and b not in vendored)
    return (not unknown), evidence(target="run_record", bands_scaled=len(scales),
                                   distinct_scales=len(set(round(s, 9)
                                                           for s in scales.values())),
                                   not_in_vendored_statistics=unknown,
                                   reason=None if not unknown
                                   else "band_absent_from_vendored_statistics")


@check(id="thirteen_channel_fusion_order_declared", weight=4, knockout=False, kind="process")
def test_thirteen_channel_fusion_order_declared():
    record = run_record()
    order = record.get("channel_fusion_order")
    if not order:
        return False, evidence(target="run_record", reason="no_channel_order_declared")
    names = [str(channel).strip().upper() for channel in order]
    if len(names) != len(set(names)):
        return False, evidence(target="run_record", declared=names[:16],
                               reason="channel_declared_more_than_once")
    bands = [n for n in names if n in BANDS]
    others = [n for n in names if n not in BANDS]
    absent = sorted(set(BANDS) - set(bands))
    if absent:
        return False, evidence(target="run_record", missing_bands=absent, declared_bands=bands,
                               reason="rgb_only_roster" if set(bands) <= set(VISIBLE_BANDS)
                               else "spectral_band_missing_from_roster")
    if len(others) != 1 or not any(t in others[0] for t in ELEVATION_TOKENS):
        return False, evidence(target="run_record", non_band_channels=others,
                               reason="elevation_channel_not_identified")
    stage = str(record.get("elevation_fusion_stage", "")).strip().lower()
    if stage not in FUSION_STAGES:
        return False, evidence(target="run_record", declared_stage=stage,
                               admitted=list(FUSION_STAGES), reason="fusion_stage_undeclared")
    return True, evidence(target="run_record", channels=len(names), spectral_bands=len(bands),
                          elevation_channel=others[0], fusion_stage=stage)


@check(id="tile_budget_declared", weight=3, knockout=False, kind="process")
def test_tile_budget_declared():
    declaration = run_record().get("agent_budget_declaration")
    if declaration is None:
        return False, evidence(target="run_record", reason="no_agent_declaration")
    try:
        fields = json.loads(declaration) if isinstance(declaration, str) else dict(declaration)
    except Exception as exc:
        return False, evidence(target="run_record", reason="declaration_unparseable",
                               error=str(exc))
    absent = [k for k in ("train_tiles", "graded_run_seconds", "inference_stride")
              if k not in fields]
    if absent:
        return False, evidence(target="run_record", declared=sorted(fields), missing=absent,
                               reason="declaration_incomplete")
    try:
        stride = int(fields["inference_stride"])
    except Exception as exc:
        return False, evidence(target="run_record", reason="stride_is_not_an_integer",
                               error=str(exc))
    edges = [min(grid) for grid in spectral_grids().values()]
    edge = min(edges) if edges else stride
    ok = 0 < stride <= edge
    return ok, evidence(target="run_record", inference_stride=stride, tile_edge=edge,
                        train_tiles=fields["train_tiles"],
                        graded_run_seconds=fields["graded_run_seconds"],
                        reason=None if ok else "stride_outside_the_tile_edge")


@check(id="vendored_encoder_only", weight=3, knockout=False, kind="integrity")
def test_vendored_encoder_only():
    provenance = run_record().get("encoder_provenance")
    if provenance is None:
        return False, evidence(target="run_record", reason="no_encoder_provenance_declared")
    text = json.dumps(provenance) if isinstance(provenance, dict) else str(provenance)
    remote = [t for t in REMOTE_ENCODER_TOKENS if t in text.lower()]
    if remote:
        return False, evidence(target="run_record", declared=text[:200], remote_tokens=remote,
                               reason="encoder_declared_from_a_remote_host")
    path = provenance.get("path") if isinstance(provenance, dict) else str(provenance)
    if path is None or str(path).strip().lower() in ("from_scratch", "none", "null", ""):
        return True, evidence(target="run_record", encoder="trained_from_scratch")
    resolved = str(path) if os.path.isabs(str(path)) else os.path.join(BUNDLE, str(path))
    inside = os.path.abspath(resolved).startswith(os.path.abspath(BUNDLE) + os.sep)
    return inside, evidence(target="run_record", encoder_path=str(path)[:200], vendored=inside,
                            reason=None if inside else "encoder_not_vendored_in_the_bundle")


# ------------------------------------------------------------------------------------------
# Reading the delivered bytes. Four archives and one record, each read the same way every
# check reads it: absent is reported, never guessed at.
# ------------------------------------------------------------------------------------------

def load_submission():
    """The keyed mask archive: one integer land-cover raster per graded tile id."""
    import numpy as np
    with np.load(SUBMISSION, allow_pickle=False) as archive:
        members = {name: archive[name] for name in archive.files}
    if not members:
        raise ValueError("the mask archive carries no members")
    return members


def archive_member_order():
    """Member names in the order the archive stores them. npz bytes depend on this order."""
    import numpy as np
    with np.load(SUBMISSION, allow_pickle=False) as archive:
        return list(archive.files)


def describe(obj):
    return ",".join("%s:%s" % (k, tuple(v.shape)) for k, v in sorted(obj.items())[:4])


def archive_shapes(path):
    """member -> shape for one of the shipped tile archives; empty when it will not read.

    Empty covers two cases and the checks distinguish them by what else is available: the
    archive has not landed in this tree, or it landed and no longer parses. The second is red
    line 1 happening in front of the verifier, so it must produce a report rather than an
    unhandled traceback -- an archive that will not open is a finding, not a crash.
    """
    import numpy as np
    if not os.path.exists(path):
        return {}
    try:
        with np.load(path, allow_pickle=False) as archive:
            return {name: tuple(archive[name].shape) for name in archive.files}
    except Exception:
        return {}


def spectral_grids():
    """tile id -> (rows, cols), the twelve-band stack with its band axis dropped."""
    return dict((tile, shape[-2:]) for tile, shape in archive_shapes(GRADED_SPECTRAL).items())


def elevation_grids():
    """tile id -> (rows, cols) of the co-registered elevation raster."""
    return dict((tile, shape[-2:]) for tile, shape in archive_shapes(GRADED_ELEVATION).items())


def graded_tile_ids():
    """The graded tile set: the private mask archive names it, the spectral stack stands in.

    Verifier-side both are mounted and they agree. In a staged tree neither may have landed,
    and every check that needs the tile set says so rather than passing over an empty one.
    """
    for path in (GRADED_MASKS, GRADED_SPECTRAL, GRADED_ELEVATION):
        shapes = archive_shapes(path)
        if shapes:
            return sorted(shapes)
    return []


def class_index():
    """The land-cover class ids the per-class mean runs over."""
    if not os.path.exists(CLASS_INDEX):
        return []
    try:
        with open(CLASS_INDEX) as handle:
            doc = json.load(handle)
        ids = doc.get("class_ids", doc.get("classes")) if isinstance(doc, dict) else doc
        if isinstance(ids, dict):
            ids = list(ids.values())
        return sorted(int(c) for c in ids)
    except Exception:
        return []


def vendored_band_statistics():
    """The per-band location and scale the corpus vendors, upper-cased by band name."""
    if not os.path.exists(BAND_STATISTICS):
        return {}
    try:
        with open(BAND_STATISTICS) as handle:
            doc = json.load(handle)
        doc = doc.get("bands", doc) if isinstance(doc, dict) else {}
        return dict((str(k).strip().upper(), v) for k, v in doc.items())
    except Exception:
        return {}


def band_scale(entry):
    """The scale a band declaration carries, whichever key it names it by."""
    if isinstance(entry, dict):
        for key in ("scale", "std", "stddev", "sigma"):
            if key in entry:
                return float(entry[key])
        raise KeyError("no scale key in band declaration")
    if isinstance(entry, (list, tuple)) and len(entry) == 2:
        return float(entry[1])
    return float(entry)


def run_record():
    """What the graded run declared about itself.

    The agent writes this file, so it can be absent, truncated, or not JSON at all. Every one
    of those is an empty record here: an unparseable declaration declares nothing, and each
    check then reports its own missing-declaration reason instead of taking the verifier down
    with a decode error and returning no report about anything.
    """
    if not os.path.exists(RUN_RECORD):
        return {}
    try:
        with open(RUN_RECORD) as handle:
            doc = json.load(handle)
    except Exception:
        return {}
    return doc if isinstance(doc, dict) else {}


def in_guarded_tree(path):
    """True when a written path lands in the checker tree or on a graded tile archive."""
    flat = "/" + str(path).replace("\\", "/").lstrip("./").lstrip("/")
    return any(token in flat for token in GUARDED_WRITES)


def archive_content_digest():
    """sha256 over member names, dtypes, shapes and raw bytes, in the archive's stored order.

    NOT the file digest. An npz is a zip and its member headers carry whatever timestamp
    convention the writing library uses, so hashing the file measures numpy's release as much
    as it measures the run. Stored order is inside this digest on purpose: member order IS a
    property of the run, and a solve that iterates a dictionary to write its tiles produces the
    same masks in a different archive.
    """
    import hashlib
    import numpy as np
    if not os.path.exists(SUBMISSION):
        return None
    digest = hashlib.sha256()
    with np.load(SUBMISSION, allow_pickle=False) as archive:
        for name in archive.files:
            member = np.ascontiguousarray(archive[name])
            digest.update(name.encode("utf-8"))
            digest.update(("%s%s" % (member.dtype.str, member.shape)).encode("utf-8"))
            digest.update(member.tobytes())
    return digest.hexdigest()


def aligned_prediction(submitted, tile, truth):
    """The submitted mask for one graded tile, or None when it is missing or off the grid.

    Off-grid is deliberately NOT resampled. A mask on another grid is not a weaker answer to
    this tile's question, it is an answer to a different one, and it scores as an empty
    prediction: full union, no intersection.
    """
    member = submitted.get(tile)
    if member is None:
        return None
    if tuple(getattr(member, "shape", ())) != tuple(truth.shape):
        return None
    return member


def measure():
    """Mean per-class IoU: pooled per land-cover class, absent classes dropped, not credited.

    Pooling is per class across the whole graded tile set, so a class that occurs in one tile
    out of a thousand still carries one full term of the mean. A class whose pooled union is
    empty contributes NO term: an empty intersection over an empty union is undefined, and
    scoring it 1.0 would pay for every class nobody predicted and no tile contained.
    """
    import numpy as np
    if not os.path.exists(GRADED_MASKS):
        raise ConstantUnmeasured(
            "the private graded mask archive is not mounted; mean per-class IoU is not "
            "measurable from these bytes and reporting a number would be inventing one")
    try:
        submitted = load_submission()
    except Exception:
        submitted = {}
    intersection, union = {}, {}
    with np.load(GRADED_MASKS, allow_pickle=False) as truth_archive:
        for tile in sorted(truth_archive.files):
            truth = np.asarray(truth_archive[tile])
            predicted = aligned_prediction(submitted, tile, truth)
            labels = set(int(v) for v in np.unique(truth))
            if predicted is not None:
                labels |= set(int(v) for v in np.unique(np.asarray(predicted)))
            for label in sorted(labels):
                hit = truth == label
                guess = (np.asarray(predicted) == label if predicted is not None
                         else np.zeros(truth.shape, dtype=bool))
                intersection[label] = intersection.get(label, 0) + int((hit & guess).sum())
                union[label] = union.get(label, 0) + int((hit | guess).sum())
    graded_classes = class_index() or sorted(union)
    per_class = [intersection.get(c, 0) / union[c] for c in graded_classes if union.get(c, 0)]
    if not per_class:
        raise ConstantUnmeasured("no land-cover class has a non-empty union over the graded tiles")
    return float(sum(per_class) / len(per_class))
